// Bad: the row depends on the whole model; any change redraws every row
ForEach(model.posts) { PostRow(model: model, post: $0) }

// Good: the row gets only what it shows
ForEach(model.posts) { post in
    PostRow(title: post.title, subtitle: post.formattedDate)
}

struct PostRow: View {
    let title: String
    let subtitle: String
    var body: some View {
        let _ = Self._printChanges()          // debug only
        VStack(alignment: .leading) { Text(title); Text(subtitle).font(.caption) }
    }
}
